"""
Minimal SOCKS5 client shim for urllib3.contrib.socks.
Implements only SOCKS5 CONNECT, remote DNS, and RFC 1929 username/password auth.
This is bundled so the fnOS package can support SOCKS5 without first-run downloads.
"""
from __future__ import annotations

import socket
import struct

PROXY_TYPE_SOCKS5 = 2


class ProxyError(OSError):
    def __init__(self, message, socket_err=None):
        super().__init__(message)
        self.socket_err = socket_err


def _recv_exact(sock, size):
    chunks = []
    remaining = size
    while remaining:
        chunk = sock.recv(remaining)
        if not chunk:
            raise OSError("SOCKS5 proxy closed the connection")
        chunks.append(chunk)
        remaining -= len(chunk)
    return b"".join(chunks)


def create_connection(address, proxy_type=None, proxy_addr=None, proxy_port=None,
                      proxy_username=None, proxy_password=None, proxy_rdns=True,
                      timeout=None, source_address=None, socket_options=None, **kwargs):
    if proxy_type != PROXY_TYPE_SOCKS5:
        raise ProxyError("Only SOCKS5 is supported by the bundled shim")
    if not proxy_addr or not proxy_port:
        raise ProxyError("SOCKS5 proxy address is incomplete")
    sock = None
    try:
        sock = socket.create_connection((proxy_addr, int(proxy_port)), timeout, source_address)
        if socket_options:
            for level, optname, value in socket_options:
                sock.setsockopt(level, optname, value)

        username = (proxy_username or "").encode("utf-8")
        password = (proxy_password or "").encode("utf-8")
        if username or password:
            if not username or not password or len(username) > 255 or len(password) > 255:
                raise OSError("Invalid SOCKS5 username/password")
            methods = b"\x00\x02"
        else:
            methods = b"\x00"
        sock.sendall(b"\x05" + bytes([len(methods)]) + methods)
        ver, method = _recv_exact(sock, 2)
        if ver != 5 or method == 0xFF:
            raise OSError("SOCKS5 proxy rejected authentication methods")
        if method == 0x02:
            if not username or not password:
                raise OSError("SOCKS5 proxy requires authentication")
            sock.sendall(b"\x01" + bytes([len(username)]) + username +
                         bytes([len(password)]) + password)
            auth_ver, auth_status = _recv_exact(sock, 2)
            if auth_ver != 1 or auth_status != 0:
                raise OSError("SOCKS5 authentication failed")
        elif method != 0x00:
            raise OSError("SOCKS5 proxy selected an unsupported authentication method")

        host, port = address
        host = str(host)
        if proxy_rdns:
            try:
                ip = socket.inet_pton(socket.AF_INET, host)
                atyp, addr = 1, ip
            except OSError:
                try:
                    ip = socket.inet_pton(socket.AF_INET6, host)
                    atyp, addr = 4, ip
                except OSError:
                    encoded = host.encode("idna")
                    if not 1 <= len(encoded) <= 255:
                        raise OSError("SOCKS5 destination hostname is invalid")
                    atyp, addr = 3, bytes([len(encoded)]) + encoded
        else:
            infos = socket.getaddrinfo(host, int(port), type=socket.SOCK_STREAM)
            if not infos:
                raise OSError("Unable to resolve SOCKS5 destination")
            family, _, _, _, sockaddr = infos[0]
            if family == socket.AF_INET6:
                atyp, addr = 4, socket.inet_pton(socket.AF_INET6, sockaddr[0])
            else:
                atyp, addr = 1, socket.inet_pton(socket.AF_INET, sockaddr[0])

        sock.sendall(b"\x05\x01\x00" + bytes([atyp]) + addr + struct.pack("!H", int(port)))
        ver, reply, _reserved, bound_type = _recv_exact(sock, 4)
        if ver != 5 or reply != 0:
            raise OSError("SOCKS5 CONNECT request failed (reply " + str(reply) + ")")
        if bound_type == 1:
            _recv_exact(sock, 4)
        elif bound_type == 4:
            _recv_exact(sock, 16)
        elif bound_type == 3:
            length = _recv_exact(sock, 1)[0]
            _recv_exact(sock, length)
        else:
            raise OSError("SOCKS5 proxy returned an invalid address type")
        _recv_exact(sock, 2)
        return sock
    except Exception as exc:
        if sock is not None:
            try:
                sock.close()
            except OSError:
                pass
        if isinstance(exc, ProxyError):
            raise
        raise ProxyError("SOCKS5 connection failed", socket_err=exc) from exc
